import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String a = scanner.next();
        int len = a.length();
        boolean flag = false;
        StringBuilder s = new StringBuilder();

        // Check if '@' exists in the input
        for (int i = 0; i < len; i++) {
            if (a.charAt(i) == '@') {
                flag = true;
                break;
            }
        }

        char[] arr = a.toCharArray();

        for (int i = 0; i < len; i++) {
            if (i + 2 < len && arr[i] == 'd' && arr[i + 1] == 'o' && arr[i + 2] == 't' && i != 0 && i != len - 3) {
                s.append('.');
                arr[i] = ' ';
                arr[i + 1] = ' ';
                arr[i + 2] = ' ';
            }
            if (i + 1 < len && arr[i] == 'a' && arr[i + 1] == 't' && i != 0 && i != len - 2 && !flag) {
                s.append('@');
                arr[i] = ' ';
                arr[i + 1] = ' ';
                flag = true;
            } else if (arr[i] != ' ') {
                s.append(arr[i]);
            }
        }

        System.out.println(s.toString());
        scanner.close();
    }
}
